const PALETTE = {
  'space-deep': 0x20283D,
  'shadow-plum': 0x765768,
  'regolith-mid': 0xB95C40,
  'regolith-light': 0xE6A26A,
  'structure-white': 0xF2E5D2,
  'structure-gray': 0x686976,
  'trim-dark': 0x303240,
  'accent-orange': 0xFF8A24,
  'accent-cyan': 0x54E5F5,
  'accent-blue': 0x35CFFF,
  'glass-tint': 0xEBD9C5,
  'cell-blue': 0x2F58B8
};

const BUDGETS = {"small-prop":1500,"medium-prop":6000,"vehicle":9000,"building":12000,"character":8000,"rock":400};
const SEGMENTS = {"small":8,"default":12,"large":16};

// Bevel radius for roundedBoxGeo: ratio of the smallest dimension (style range 0.06-0.12).
function bevel(w, h, d, ratio = 0.09) {
  return Math.min(w, h, d) * ratio;
}

// One shared material per role. Variants (e.g. structure-gray) take an explicit colour token.
function styleMaterials() {
  const m = {"matte-environment":{"description":"Terrain, rocks, craters, mountains. Fully matte, no reflections.","colors":["regolith-mid","regolith-light","shadow-plum"],"roughness":0.95,"metalness":0},"smooth-structure":{"description":"Buildings, modules, vehicles, suits, crates. Clean satin finish, never mirror-like.","colors":["structure-white","structure-gray"],"roughness":0.55,"metalness":0.05},"accent-paint":{"description":"Non-glowing orange colour blocking: side panels, crate faces, dome base band, suit pads, wheel hubs.","colors":["accent-orange"],"roughness":0.6,"metalness":0},"dark-trim":{"description":"Tyres, recesses, joints, vents.","colors":["trim-dark"],"roughness":0.85,"metalness":0},"emissive-warm":{"description":"Door frames, window strips, headlights. Selected surfaces only.","colors":["accent-orange"],"emissive":"accent-orange","emissiveIntensity":1.6,"roughness":0.5,"metalness":0},"emissive-cool":{"description":"Beacons, indicators, screens. Smaller and rarer than warm lights.","colors":["accent-cyan","accent-blue"],"emissive":"accent-cyan","emissiveIntensity":1.4,"roughness":0.5,"metalness":0},"glass":{"description":"Greenhouse domes, module windows. Light tint, soft highlight, see-through.","colors":["glass-tint"],"roughness":0.15,"metalness":0,"opacity":0.35},"visor":{"description":"Helmet visors and vehicle windshields. Opaque near-black, glossy, shows a soft highlight.","colors":["space-deep"],"roughness":0.12,"metalness":0.1},"solar-cell":{"description":"Solar panel cell faces. Deep blue, semi-gloss, framed by structure-white grid bars.","colors":["cell-blue"],"roughness":0.35,"metalness":0.1}};
  const make = (role, colorToken) => {
    const spec = m[role];
    const color = PALETTE[colorToken ?? spec.colors[0]];
    const name = colorToken && colorToken !== spec.colors[0] ? role + ':' + colorToken : role;
    if (role === 'glass') return glassMaterial(color, { opacity: spec.opacity, roughness: spec.roughness, metalness: spec.metalness, name });
    const opts = { roughness: spec.roughness, metalness: spec.metalness, name };
    if (spec.emissive) Object.assign(opts, { emissive: PALETTE[spec.emissive], emissiveIntensity: spec.emissiveIntensity });
    return gameMaterial(color, opts);
  };
  return {
    rock: make('matte-environment'),
    rockLight: make('matte-environment', 'regolith-light'),
    rockShadow: make('matte-environment', 'shadow-plum'),
    panel: make('smooth-structure'),
    panelGray: make('smooth-structure', 'structure-gray'),
    accent: make('accent-paint'),
    trim: make('dark-trim'),
    glowWarm: make('emissive-warm'),
    glowCool: make('emissive-cool'),
    glowBlue: make('emissive-cool', 'accent-blue'),
    glass: make('glass'),
    visor: make('visor'),
    solarCell: make('solar-cell'),
  };
}
// ---- end style header ----

const meta = { name: 'Mars Rover', role: 'vehicle' };

// Closed octagonal cross-sections lofted along +X. Each face has split normals.
function octagonalHull(stations) {
  const rings = stations.map(([x, low, high, width, cut]) => [
    [x,low,-width+cut], [x,low+cut,-width],
    [x,high-cut,-width], [x,high,-width+cut],
    [x,high,width-cut], [x,high-cut,width],
    [x,low+cut,width], [x,low,width-cut],
  ]);
  const positions = [];
  function triangle(a,b,c) { positions.push(...a,...b,...c); }
  for(let j=0;j<rings.length-1;j++) for(let k=0;k<8;k++) {
    const n=(k+1)%8;
    triangle(rings[j][k],rings[j][n],rings[j+1][n]);
    triangle(rings[j][k],rings[j+1][n],rings[j+1][k]);
  }
  for(const [j,reverse] of [[0,true],[rings.length-1,false]]) {
    const r=rings[j]; const center=[r[0][0],(stations[j][1]+stations[j][2])/2,0];
    for(let k=0;k<8;k++) {
      const n=(k+1)%8;
      if(reverse) triangle(center,r[n],r[k]); else triangle(center,r[k],r[n]);
    }
  }
  const geo=new THREE.BufferGeometry();
  geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));
  geo.computeVertexNormals();
  return geo;
}

async function build() {
  const root=createRoot('MarsRover');
  const M=styleMaterials();
  const wheelY=0.56, wheelZ=0.96, tireRadius=0.52;
  const axleXs=[1.27,-0.04,-1.35];
  const attach=(name,geo,mat,pos=[0,0,0],rot=[0,0,0],parent=root)=>
    createPart(name,geo,mat,{position:pos,rotation:rot,parent});
  const block=async(name,dims,pos,mat=M.panel,ratio=0.09,parent=root,rot=[0,0,0])=>
    attach(name,await roundedBoxGeo(...dims,bevel(...dims,ratio),{style:'chamfer'}),mat,pos,rot,parent);

  await block('ArmouredChassis',[4.14,0.38,1.52],[0,0.88,0],M.panelGray,0.18);
  await block('LowerKeel',[3.4,0.25,1.15],[-0.1,0.67,0],M.trim,0.16);

  // Cabin front drops through a single broad windshield plane to a shallow hood.
  attach('CabinHull',octagonalHull([
    [-0.48,1.04,2.03,0.77,0.12],[-0.32,0.99,2.10,0.84,0.12],
    [0.49,0.99,2.10,0.84,0.12],[1.26,0.97,1.35,0.84,0.12],
    [2.05,0.94,1.25,0.78,0.10],[2.15,1.00,1.20,0.69,0.07],
  ]),M.panel);
  attach('RearHabitatHull',octagonalHull([
    [-2.10,1.02,1.79,0.70,0.10],[-1.96,0.98,1.96,0.81,0.13],
    [-0.65,0.98,2.03,0.83,0.13],[-0.49,1.04,1.96,0.76,0.12],
  ]),M.panel);
  await block('CabinRearCollar',[0.15,0.99,1.73],[-0.52,1.51,0],M.panelGray,0.13);

  // Windshield sits on the sloping roof between X=.49 and X=1.26.
  const windshieldAngle=Math.atan2(0.77,0.75)*180/Math.PI;
  await block('WindshieldGasket',[0.065,0.98,1.42],[0.887,1.750,0],M.panelGray,0.09,root,[0,0,windshieldAngle]);
  await block('FrontWindshield',[0.035,0.84,1.26],[0.917,1.780,0],M.visor,0.10,root,[0,0,windshieldAngle]);
  await block('HoodInset',[0.61,0.045,1.10],[1.61,1.321,0],M.panelGray,0.14,root,[0,0,-7.2]);
  await block('HoodLatch',[0.13,0.025,0.32],[1.57,1.35,0],M.trim,0.08);

  await block('HeadlightRecess',[0.14,0.25,1.52],[2.12,1.13,0],M.accent,0.15);
  await block('HeadlightGasket',[0.035,0.155,1.34],[2.198,1.14,0],M.trim,0.09);
  for(const z of [-0.50,0.50]) await block('Headlamp_'+z,[0.045,0.125,0.25],[2.226,1.14,z],M.glowWarm,0.12);
  await block('CenterHeadlightStrip',[0.045,0.055,0.56],[2.226,1.14,0],M.glowWarm,0.10);
  await block('FrontBumper',[0.23,0.18,1.60],[2.11,0.89,0],M.panelGray,0.20);
  await block('BumperOrangeInsert',[0.045,0.10,1.07],[2.24,0.90,0],M.accent,0.10);
  await block('FrontTowSlot',[0.049,0.045,0.38],[2.267,0.90,0],M.trim,0.10);
  await block('RearBumper',[0.20,0.18,1.57],[-2.10,0.89,0],M.panelGray,0.18);

  const sideWindow=await extrudeProfile([
    [-0.17,1.57],[0.88,1.57],[0.42,1.99],[-0.17,1.99]
  ],{axis:'z',depth:0.025,bevel:0.04,bevelStyle:'chamfer'});
  const windowFrame=await extrudeProfile([
    [-0.25,1.50],[1.02,1.50],[0.47,2.06],[-0.25,2.06]
  ],{axis:'z',depth:0.032,bevel:0.045,bevelStyle:'chamfer'});
  const fenderProfile=[[-0.66,0.85],[-0.61,1.11],[-0.36,1.32],[0.36,1.32],[0.61,1.11],[0.66,0.85],
    [0.51,0.85],[0.47,1.00],[0.28,1.16],[-0.28,1.16],[-0.47,1.00],[-0.51,0.85]];
  const fenderGeo=await extrudeProfile(fenderProfile,{axis:'z',depth:0.47,bevel:0.015,bevelStyle:'chamfer'});
  const treadGeo=boxGeo(0.19,0.07,0.47);
  const tireProfile=[
    [0.29,-0.22],[0.44,-0.22],[0.50,-0.16],[tireRadius,-0.10],
    [tireRadius,0.10],[0.50,0.16],[0.44,0.22],[0.29,0.22],[0.29,-0.22],
  ].map(([r,y])=>new THREE.Vector2(r,y));
  const tireGeo=new THREE.LatheGeometry(tireProfile,SEGMENTS.large);
  tireGeo.rotateX(Math.PI/2);
  const rimGeo=cylinderGeo(0.347,0.347,0.47,SEGMENTS.large);
  const orangeGeo=cylinderGeo(0.287,0.287,0.493,SEGMENTS.large);
  const hubGeo=cylinderGeo(0.205,0.205,0.513,SEGMENTS.default);
  const axleGeo=cylinderGeo(0.10,0.10,1.95,SEGMENTS.default);

  for(let i=0;i<axleXs.length;i++) {
    const x=axleXs[i];
    attach('Axle_'+i,axleGeo,M.panelGray,[x,wheelY,0],[90,0,0]);
    for(const side of [-1,1]) {
      const name=(side<0?'Left':'Right')+['Front','Middle','Rear'][i];
      const wheel=new THREE.Group(); wheel.name=name+'Wheel';
      wheel.position.set(x,wheelY,side*wheelZ); root.add(wheel);
      attach(name+'Tyre',tireGeo,M.trim,[0,0,0],[0,0,0],wheel);
      attach(name+'Rim',rimGeo,M.panelGray,[0,0,0],[90,0,0],wheel);
      attach(name+'OrangeHub',orangeGeo,M.accent,[0,0,0],[90,0,0],wheel);
      attach(name+'HubCap',hubGeo,M.accent,[0,0,0],[90,0,0],wheel);
      const treads=new THREE.Group();treads.name=name+'Treads';wheel.add(treads);
      for(let j=0;j<16;j++) {
        const a=j*Math.PI/8;
        attach(name+'Tread_'+j,treadGeo,M.trim,[0.525*Math.sin(a),0.525*Math.cos(a),0],[0,0,-j*22.5],treads);
      }
      repeatInstances(treads);
      attach(name+'Fender',fenderGeo,M.panelGray,[x,0,side*0.91]);
      await block(name+'SuspensionArm',[0.23,0.36,0.18],[x,wheelY+0.12,side*0.76],M.panelGray,0.10);
    }
  }

  for(const side of [-1,1]) {
    attach('SideWindowFrame_'+side,windowFrame,M.panelGray,[0,0,side*0.842]);
    attach('SideWindow_'+side,sideWindow,M.visor,[0,0,side*0.864]);
    await block('SideDoorInset_'+side,[0.57,0.68,0.055],[-0.03,1.44,side*0.83],M.panel,0.12);
    await block('DoorOrangePanel_'+side,[0.46,0.23,0.055],[-0.03,1.35,side*0.876],M.accent,0.14);
    await block('DoorHandle_'+side,[0.12,0.065,0.04],[-0.19,1.63,side*0.88],M.panelGray,0.12);
    await block('RearOrangePanel_'+side,[0.89,0.19,0.045],[-1.28,1.38,side*0.823],M.accent,0.13);
    await block('RearSideWindowFrame_'+side,[0.43,0.27,0.04],[-1.18,1.77,side*0.817],M.panelGray,0.15);
    await block('RearSideWindow_'+side,[0.34,0.18,0.045],[-1.18,1.77,side*0.843],M.visor,0.13);
    await block('SideStep_'+side,[0.65,0.09,0.26],[-0.10,0.94,side*0.92],M.panelGray,0.10);
    for(let k=0;k<3;k++) await block('RearVent_'+side+'_'+k,[0.15,0.045,0.025],[-1.76,1.74-k*0.085,side*0.826],M.trim,0.08);
    await block('RearMarker_'+side,[0.045,0.09,0.18],[-2.116,1.23,side*0.53],M.glowWarm,0.10);
  }

  await block('RoofRackPlatform',[1.42,0.08,1.20],[-1.16,2.01,0],M.panelGray,0.14);
  for(const z of [-0.30,0.30]) await block('CargoMount_'+z,[0.94,0.11,0.08],[-1.18,2.06,z],M.panelGray,0.1);
  await block('RoofCargoLarge',[0.70,0.31,0.75],[-1.30,2.20,0],M.panelGray,0.16);
  await block('CargoOrangeBand',[0.17,0.32,0.76],[-1.22,2.20,0],M.accent,0.08);
  await block('RoofCargoSmall',[0.46,0.20,0.49],[-0.64,2.15,0],M.panel,0.15);
  for(const z of [-0.43,0.43]) await block('LightbarFoot_'+z,[0.13,0.10,0.11],[0.18,2.12,z],M.panelGray,0.10);
  await block('RoofLightbarHousing',[0.20,0.21,1.03],[0.18,2.25,0],M.panelGray,0.12);
  await block('RoofCyanLightbar',[0.035,0.115,0.82],[0.294,2.25,0],M.glowCool,0.10);
  await block('AntennaBase',[0.24,0.10,0.24],[-1.79,2.04,-0.42],M.panelGray,0.14);
  attach('AntennaMast',cylinderGeo(0.022,0.032,0.47,SEGMENTS.small),M.panelGray,[-1.79,2.315,-0.42]);
  await block('AntennaTip',[0.16,0.12,0.14],[-1.79,2.57,-0.42],M.panelGray,0.14);
  await block('AntennaCyanIndicator',[0.025,0.055,0.075],[-1.699,2.57,-0.42],M.glowCool,0.10);

  defineBudget({triangles:BUDGETS.vehicle},root);
  return root;
}
